update z000_sd_pay_receipt_header
set buss_status = #{bussStatus}
, buss_doc_id = #{bussDocId}
where receipt_id = #{bussId}

update z000_sd_pay_receipt_header
set sap_mess_id = #{sapMessId}, sap_msg = #{sapMsg}
where receipt_id = #{receiptId}

update z000_sd_pay_receipt_header
set vch_num = #{vchNum}, vch_year = #{vchYear},
    sap_mess_id = #{sapMessId}, sap_msg = #{sapMsg}
where receipt_id = #{receiptId}

update z000_sd_pay_receipt_header
set vch_num_reverse = #{vchNumReverse}, vch_year_reverse = #{vchYearReverse},
    sap_mess_id = #{sapMessId}, sap_msg = #{sapMsg}
where receipt_id = #{receiptId}
